import{z as n,x as s,o as e,c as d,q as l,j as i,D as B,d as A,s as t,S as o,b as a}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"Reward hacking 的监控","description":"","frontmatter":{"title":"Reward hacking 的监控","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rlsys-hacking-monitor.md","filePath":"llm/rlsys-hacking-monitor.md","lastUpdated":1791413859000}'),m={name:"llm/rlsys-hacking-monitor.md"};function h(F,E,C,p,D,c){const r=s("Mermaid");return e(),d("div",null,[E[2]||(E[2]=l('<h1 id="reward-hacking-的监控" tabindex="-1">Reward hacking 的监控 <a class="header-anchor" href="#reward-hacking-的监控" aria-label="Permalink to &quot;Reward hacking 的监控&quot;">​</a></h1><div class="epigraph"><p>训练曲线全是好消息的时候，最先该怀疑的是仪表——代理奖励只会报告它自己被优化的程度。</p><footer>—— 据 Gao、Schulman、Hilton 2022 与 Skalse 等 2022 的定义整理</footer></div><p><a href="/llm/rlsys-async-debug">上一课</a>让系统跑得又快又不静默出错；本课转向另一类「没有 bug 的错」：系统精确优化了你给的目标，而那个目标不是你要的。Reward hacking 的机制面在<a href="/llm/reward-hacking-llm">奖励黑客</a>与<a href="/llm/rm-overoptimization">RM 过优化与 Goodhart</a>讲过，本课写工程面：把黑客行为变成在线上会触发告警的曲线。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>黑客的定义性困难是「代理分数上升，真实质量没跟上」——而真实质量没有实时标签。你手里只有代理奖励的实时曲线，和昂贵的、按天到周级的离线金标。缺口是把间接证据组织成可告警的信号：什么指标组合出现什么形态时，应该停下训练而不是继续看。难点在于单指标都不可靠：奖励涨可能是真进步也可能是钻空；长度变长可能是学会详尽也可能是凑字；KL 小可能是稳定也可能是局部锁死。监控设计的任务，是用一组彼此正交的便宜信号逼近那个没有实时标签的真值。</p><p><span class="marginnote">「代理奖励」翻译成大白话：RM 或验证器给的分。真正想要的「真实质量」没法实时打分，只好用这个可计算的替身代劳——「代理」即「替身」。替身演得越卖力（分数涨得越快），越要先问一句：它是在替目标涨分，还是在替自己抢戏？</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>面板按「代理对金标」的主线组织，四组信号。交叉对照：代理奖励与独立金标（人审抽检、强裁判、可验证子集）双线同图——同升是健康，代理独升即黑客签名，报警并停训排查。行为统计：响应长度分布、格式特征率（代码块数、列表密度、模板开头复读）、重复度、熵——黑客几乎总要占用某个便宜的表面通道，统计漂移比语义劣化早几天现形。约束仪表：对 \\(\\pi_{\\mathrm{ref}}\\) 的 KL、熵、奖励分量分解——KL 突跳与熵坍缩都是前兆，分量分解回答「哪个通道在被钻」。抽查队列：按代理分位分层抽样送人审或强裁判，让「高分样本真的好吗」始终有人回答。告警规则宁滥勿缺：交叉背离即报警，单指标漂移进人工复核。</p><p><span class="marginnote">常见误区：KL 小不等于安全。初学者容易把「KL 很小」当训练稳定的证据，实际上它也可能意味着策略锁死在某个模式附近不动了——不是没跑偏，而是跑不动了。所以 KL 要和熵一起读：KL 突跳查黑客，熵坍缩查锁死，两条曲线分工不同。</span></p><p><span class="marginnote">长度是最低成本的黑客通道：若长度分布的分位数一周内上移两成而金标持平，第一反应应是查黑客而不是庆祝进步——它与 RM 侧的长度去偏（<a href="/llm/rm-length-bias">长度偏置的测量与去偏</a>）是同一枚硬币的两面。</span></p>',10)),(e(),i(o,null,{default:B(()=>[t(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E4%BB%A3%E7%90%86%E5%A5%96%E5%8A%B1%E6%9B%B2%E7%BA%BF%22%5D%20--%3E%20X%7B%22%E4%B8%8E%E9%87%91%E6%A0%87%E5%AF%B9%E7%85%A7%22%7D%0A%20%20G%5B%22%E9%87%91%E6%A0%87%EF%BC%9A%E4%BA%BA%E5%AE%A1%2F%E5%BC%BA%E8%A3%81%E5%88%A4%2F%E5%8F%AF%E9%AA%8C%E8%AF%81%E5%AD%90%E9%9B%86%22%5D%20--%3E%20X%0A%20%20X%20--%3E%7C%22%E5%90%8C%E5%8D%87%22%7C%20OK%5B%22%E5%81%A5%E5%BA%B7%EF%BC%9A%E7%BB%A7%E7%BB%AD%22%5D%0A%20%20X%20--%3E%7C%22%E4%BB%A3%E7%90%86%E7%8B%AC%E5%8D%87%22%7C%20ALERT%5B%22%E9%BB%91%E5%AE%A2%E7%AD%BE%E5%90%8D%EF%BC%9A%E5%81%9C%E8%AE%AD%E6%8E%92%E6%9F%A5%22%5D%0A%20%20B%5B%22%E8%A1%8C%E4%B8%BA%E7%BB%9F%E8%AE%A1%EF%BC%9A%E9%95%BF%E5%BA%A6%2F%E6%A0%BC%E5%BC%8F%2F%E9%87%8D%E5%A4%8D%2F%E7%86%B5%22%5D%20--%3E%20DRIFT%5B%22%E6%BC%82%E7%A7%BB%E6%A3%80%E6%B5%8B%20%E2%86%92%20%E4%BA%BA%E5%B7%A5%E5%A4%8D%E6%A0%B8%22%5D%0A%20%20K%5B%22KL%20%E4%B8%8E%E7%86%B5%E4%BB%AA%E8%A1%A8%20%2B%20%E5%88%86%E9%87%8F%E5%88%86%E8%A7%A3%22%5D%20--%3E%20DRIFT%0A"})]),fallback:B(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[A("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,[A("为什么交叉对照是主线：Goodhart 的各形态里（"),a("a",{href:"/llm/rm-overoptimization"},"RM 过优化与 Goodhart"),A("），代理先升、金标后滞之间有一个窗口期，监控买的就是这个窗口。行为统计的机制价值在于便宜：它们从已有经验流里零成本算出，能以分钟级新鲜度持续在线；金标只能按天到周级抽检，注定只能做确认而非发现。约束仪表回答「策略还有没有探索能力」：熵坍缩后策略锁死在当前模式，hack 与退化的区分已失去意义，先救探索再谈别的。奖励分量分解把优化压力的流向摊开：长度分量、格式分量、内容分量各自贡献多少，被钻的通道一目了然，处置（收紧 RM、加惩罚、回滚）才有靶子。")],-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"直觉类比：代理与金标像两个并排跑步的人，健康时同速前进；开始作弊时代理会突然加速而金标原地踏步——这段差距拉开的窗口期，就是监控能买到的全部时间。等金标也掉头向下，损失已经发生，报警就成了验尸报告。")],-1)),(e(),i(o,null,{default:B(()=>[t(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20S1%5B%22%E5%88%86%E9%92%9F%E7%BA%A7%EF%BC%9A%E9%95%BF%E5%BA%A6%20%2F%20%E6%A0%BC%E5%BC%8F%20%2F%20%E9%87%8D%E5%A4%8D%20%2F%20%E7%86%B5%E6%BC%82%E7%A7%BB%22%5D%20--%3E%7C%22%E5%8F%91%E7%8E%B0%EF%BC%9A%E4%BE%BF%E5%AE%9C%E4%BF%A1%E5%8F%B7%22%7C%20REV%5B%22%E4%BA%BA%E5%B7%A5%E5%A4%8D%E6%A0%B8%E9%98%9F%E5%88%97%22%5D%0A%20%20S2%5B%22%E6%AD%A5%E7%BA%A7%EF%BC%9AKL%20%E7%AA%81%E8%B7%B3%20%2F%20%E7%86%B5%E5%9D%8D%E7%BC%A9%20%2F%20%E5%88%86%E9%87%8F%E5%88%86%E8%A7%A3%22%5D%20--%3E%20REV%0A%20%20REV%20--%3E%7C%22%E7%96%91%E4%BC%BC%22%7C%20X%5B%22%E4%BA%A4%E5%8F%89%E5%AF%B9%E7%85%A7%EF%BC%9A%E4%BB%A3%E7%90%86%20vs%20%E9%87%91%E6%A0%87%22%5D%0A%20%20X%20--%3E%7C%22%E4%BB%A3%E7%90%86%E7%8B%AC%E5%8D%87%22%7C%20STOP%5B%22%E7%A1%AE%E8%AE%A4%E9%BB%91%E5%AE%A2%EF%BC%9A%E5%81%9C%E8%AE%AD%22%5D%0A%20%20X%20--%3E%7C%22%E5%8F%8C%E5%8F%8C%E5%90%8C%E5%8D%87%22%7C%20PASS%5B%22%E5%88%A4%E4%B8%BA%E7%9C%9F%E8%BF%9B%E6%AD%A5%EF%BC%9A%E7%BB%A7%E7%BB%AD%22%5D%0A%20%20STOP%20--%3E%20FIX%5B%22%E5%AE%9A%E4%BD%8D%E8%A2%AB%E9%92%BB%E9%80%9A%E9%81%93%20%E2%86%92%20%E6%94%B6%E7%B4%A7%20RM%20%2F%20%E5%8A%A0%E6%83%A9%E7%BD%9A%20%2F%20%E5%9B%9E%E6%BB%9A%22%5D%0A"})]),fallback:B(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>监控不解决黑客，只提前发现；处置是奖励工程的存量问题。金标本身可被攻击：人审流程或裁判提示若泄漏进训练数据，金标线也会失真——监控系统的完整性依赖它与训练环的隔离（评测数据的卫生在下一课展开）。可验证域不是免检区：测试通过率上升可能是过拟合测试集，<a href="/llm/verifiable-reward">可验证奖励</a>的验证器同样要留 held-out。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>监控主线是代理与金标的交叉对照：同升健康、代理独升即黑客签名，告警宁滥勿缺。</li><li>行为统计（长度、格式、重复、熵）零成本分钟级在线，漂移比语义劣化早现形。</li><li>KL 与熵是探索能力仪表：突跳查 hack，坍缩查锁死；分量分解定位被钻的通道。</li><li>金标与训练环必须隔离，否则监控自身失真；可验证域也要留 held-out 测试。</li><li>出处：Gao、Schulman、Hilton，2022；Skalse 等，2022；据开源 RLHF 运维实践整理。</li></ul>',4))])}const k=n(m,[["render",h]]);export{u as __pageData,k as default};
